-- Keep trigger bodies on one line for D1's remote statement parser.
CREATE TRIGGER validate_claim BEFORE INSERT ON claim BEGIN SELECT RAISE(ABORT, 'EVENT_UNAVAILABLE') WHERE NOT EXISTS (SELECT 1 FROM event JOIN spot ON spot.event_id = event.id WHERE event.id = NEW.event_id AND spot.id = NEW.spot_id AND event.status = 'active' AND event.starts_at <= NEW.created_at AND event.ends_at > NEW.created_at AND spot.amount = NEW.amount); END;
